{
  "problem_statement": "Hermes Desktop on macOS intermittently renders the same assistant reply twice even though the gateway persisted only one message row and emitted one completion, likely due to a history/live reconciliation identity mismatch between a timestamp-index-assistant root and an assistant-stream root.",
  "duplicate_query": "duplicate assistant reply macOS Desktop assistant-stream timestamp-index-assistant folded history d0288be5"
}

{
  "problem_statement": "The email adapter's `_attach_file` builds the Content-Disposition header by string-interpolating the filename, so names containing spaces, semicolons, or non-ASCII characters are truncated or RFC 2047-encoded into an invalid header, causing attachments to lose their filename or not be recognized as attachments at all.",
  "duplicate_query": "email attachment filename Content-Disposition _attach_file"
}

{
  "problem_statement": "On Windows, `hermes update` always exits 1 because the post-relaunch gateway verification cannot recognize a Desktop-started gateway whose command line uses an inline `python -c` bootstrap source, and the failed verification also unlinks the running gateway's identity files and re-spawns it on retry.",
  "duplicate_query": "Windows gateway relaunch verification inline source update exit 1"
}

{
  "problem_statement": "The CLI `/skin <name>` command lowercases the argument before matching against available skins, so user-defined skins whose names contain uppercase letters (e.g. `MyTheme`) can never be selected.",
  "duplicate_query": "skin command case sensitive lower list_skins"
}

{
  "problem_statement": "The SenseNova custom provider misclassifies the `insufficient_quota` error as a billing error rather than a rate-limit error, causing incorrect error handling in the agent core.",
  "duplicate_query": "SenseNova insufficient_quota rate limit billing error"
}

{
  "problem_statement": "The desktop app's transcript-tail cache can leave a session permanently frozen on stale transcript content (surviving restarts) because a detached websocket prevents the authoritative reconcile from overwriting the cached tail, and the cache entry is never invalidated.",
  "duplicate_query": "transcript-tail cache stale detach reconcile localStorage"
}

{
  "problem_statement": "Kanban review handoffs can be omitted or routed to stale reviewer names, so they need to be sent to a valid installed reviewer profile.",
  "duplicate_query": "kanban review handoffs default_reviewer reviewers dispatcher"
}

{
  "problem_statement": "Opt-in v2 checkpoint providers cannot access the complete pre-compression transcript because the evidence list normalizes messages and omits tool output, so an external archival provider needs the raw messages passed through the checkpoint hook.",
  "duplicate_query": "raw transcript checkpoint provider raw_messages pre-compression"
}

{
  "problem_statement": "JavaScript formatting and lint issues need to be auto-fixed via `npm run fix`.",
  "duplicate_query": "fmt js npm run fix auto-fix lint"
}
